import {
  $deleteTableColumnAtSelection,
  $deleteTableRowAtSelection,
  $getTableCellNodeFromLexicalNode,
  $getTableNodeFromLexicalNodeOrThrow,
  $insertTableColumnAtSelection,
  $insertTableRowAtSelection,
  $isTableSelection,
} from "@lexical/table";
import { $getSelection, $isRangeSelection, type LexicalEditor } from "lexical";

export const insertTableRows = (
  editor: LexicalEditor,
  insertAfter: boolean,
  count: number
) => {
  editor.update(() => {
    for (let index = 0; index < count; index += 1) {
      $insertTableRowAtSelection(insertAfter);
    }
  });
};

export const insertTableColumns = (
  editor: LexicalEditor,
  insertAfter: boolean,
  count: number
) => {
  editor.update(() => {
    for (let index = 0; index < count; index += 1) {
      $insertTableColumnAtSelection(insertAfter);
    }
  });
};

export const deleteSelectedTableRow = (editor: LexicalEditor) => {
  editor.update(() => {
    $deleteTableRowAtSelection();
  });
};

export const deleteSelectedTableColumn = (editor: LexicalEditor) => {
  editor.update(() => {
    $deleteTableColumnAtSelection();
  });
};

export const deleteSelectedTable = (editor: LexicalEditor) => {
  editor.update(() => {
    const selection = $getSelection();
    if (!($isRangeSelection(selection) || $isTableSelection(selection))) {
      return;
    }

    const tableCellNode = $getTableCellNodeFromLexicalNode(
      selection.anchor.getNode()
    );
    if (!tableCellNode) {
      return;
    }

    $getTableNodeFromLexicalNodeOrThrow(tableCellNode).remove();
  });
};

export const DEFAULT_INSERT_TABLE_PAYLOAD = {
  columns: "3",
  includeHeaders: true,
  rows: "3",
} as const;

import type { ExtraEditorFeature } from "../../core/types";
import { TableBehaviorPlugin } from "./plugin";

/**
 * Installs the table *behavior* feature: cell menus, row/column actions and
 * merge controls. The base `TableNode`, its markdown transformer and the
 * insert command stay in core so tables keep working for paste even when
 * this item is not installed — it only upgrades the editing UX. Ships as the
 * `editor-tables` registry item.
 */
export const tableFeature: ExtraEditorFeature = {
  id: "tables",
  plugin: TableBehaviorPlugin,
};

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { Columns2Icon, Rows3Icon, Trash2Icon } from "lucide-react";
import type { MouseEvent } from "react";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import {
  deleteSelectedTable,
  deleteSelectedTableColumn,
  deleteSelectedTableRow,
  insertTableColumns,
  insertTableRows,
} from "./actions";
import type { SelectionCounts } from "./types";

interface TableActionMenuProps {
  onClose: () => void;
  selectionCounts: SelectionCounts;
}

export function TableActionMenu({
  onClose,
  selectionCounts,
}: TableActionMenuProps) {
  const [editor] = useLexicalComposerContext();

  const handleMouseDown = (event: MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const rowLabel =
    selectionCounts.rows === 1 ? "row" : `${selectionCounts.rows} rows`;
  const columnLabel =
    selectionCounts.columns === 1
      ? "column"
      : `${selectionCounts.columns} columns`;

  return (
    <div className="flex w-56 flex-col gap-1 p-1">
      <Button
        className="justify-start"
        onClick={() => {
          insertTableRows(editor, false, selectionCounts.rows);
          onClose();
        }}
        onMouseDown={handleMouseDown}
        size="sm"
        type="button"
        variant="ghost"
      >
        <Rows3Icon />
        <span>Insert {rowLabel} above</span>
      </Button>
      <Button
        className="justify-start"
        onClick={() => {
          insertTableRows(editor, true, selectionCounts.rows);
          onClose();
        }}
        onMouseDown={handleMouseDown}
        size="sm"
        type="button"
        variant="ghost"
      >
        <Rows3Icon />
        <span>Insert {rowLabel} below</span>
      </Button>
      <Button
        className="justify-start"
        onClick={() => {
          insertTableColumns(editor, false, selectionCounts.columns);
          onClose();
        }}
        onMouseDown={handleMouseDown}
        size="sm"
        type="button"
        variant="ghost"
      >
        <Columns2Icon />
        <span>Insert {columnLabel} left</span>
      </Button>
      <Button
        className="justify-start"
        onClick={() => {
          insertTableColumns(editor, true, selectionCounts.columns);
          onClose();
        }}
        onMouseDown={handleMouseDown}
        size="sm"
        type="button"
        variant="ghost"
      >
        <Columns2Icon />
        <span>Insert {columnLabel} right</span>
      </Button>
      <Separator className="my-1" />
      <Button
        className="justify-start"
        onClick={() => {
          deleteSelectedTableRow(editor);
          onClose();
        }}
        onMouseDown={handleMouseDown}
        size="sm"
        type="button"
        variant="ghost"
      >
        <Trash2Icon />
        <span>Delete row</span>
      </Button>
      <Button
        className="justify-start"
        onClick={() => {
          deleteSelectedTableColumn(editor);
          onClose();
        }}
        onMouseDown={handleMouseDown}
        size="sm"
        type="button"
        variant="ghost"
      >
        <Trash2Icon />
        <span>Delete column</span>
      </Button>
      <Button
        className="justify-start text-destructive hover:text-destructive"
        onClick={() => {
          deleteSelectedTable(editor);
          onClose();
        }}
        onMouseDown={handleMouseDown}
        size="sm"
        type="button"
        variant="ghost"
      >
        <Trash2Icon />
        <span>Delete table</span>
      </Button>
    </div>
  );
}

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { TablePlugin } from "@lexical/react/LexicalTablePlugin";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";
import { mergeRegister } from "@lexical/utils";
import {
  COMMAND_PRIORITY_CRITICAL,
  isDOMNode,
  SELECTION_CHANGE_COMMAND,
} from "lexical";
import { ChevronDownIcon } from "lucide-react";
import { useEffect, useEffectEvent, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { TableActionMenu } from "./menu";
import {
  areSelectionCountsEqual,
  DEFAULT_SELECTION_COUNTS,
  readTableMenuContext,
} from "./selection";
import type {
  ButtonPosition,
  SelectionCounts,
  TableMenuContext,
} from "./types";

function TableCellActionMenuContainer({
  anchorElem,
}: {
  anchorElem: HTMLElement;
}) {
  const [editor] = useLexicalComposerContext();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const [position, setPosition] = useState<ButtonPosition>({ left: 0, top: 0 });
  const [selectionCounts, setSelectionCounts] = useState<SelectionCounts>(
    DEFAULT_SELECTION_COUNTS
  );
  const isMenuOpenRef = useRef(false);
  const isMenuClosingRef = useRef(false);
  const activeCellKeyRef = useRef<TableMenuContext["cellKey"] | null>(null);

  const setMenuOpen = (open: boolean) => {
    isMenuOpenRef.current = open;
    setIsMenuOpen(open);
  };

  const applyMenuContext = (context: TableMenuContext) => {
    activeCellKeyRef.current = context.cellKey;
    setPosition((currentPosition) => {
      return currentPosition.left === context.position.left &&
        currentPosition.top === context.position.top
        ? currentPosition
        : context.position;
    });
    setSelectionCounts((currentCounts) => {
      return areSelectionCountsEqual(currentCounts, context.selectionCounts)
        ? currentCounts
        : context.selectionCounts;
    });
    setIsVisible((currentIsVisible) =>
      currentIsVisible ? currentIsVisible : true
    );
  };

  const hideMenu = () => {
    activeCellKeyRef.current = null;
    setIsVisible((currentIsVisible) =>
      currentIsVisible ? false : currentIsVisible
    );
    setSelectionCounts((currentCounts) => {
      return areSelectionCountsEqual(currentCounts, DEFAULT_SELECTION_COUNTS)
        ? currentCounts
        : DEFAULT_SELECTION_COUNTS;
    });
  };

  const closeMenuAtCurrentPosition = () => {
    isMenuClosingRef.current = true;
    setMenuOpen(false);
  };

  const syncMenuToSelection = () => {
    editor.getEditorState().read(() => {
      const context = readTableMenuContext(editor, anchorElem);

      if (!context) {
        hideMenu();
        return;
      }

      applyMenuContext(context);
    });
  };

  const updateMenu = useEffectEvent(() => {
    editor.getEditorState().read(() => {
      const context = readTableMenuContext(editor, anchorElem);

      if (isMenuClosingRef.current) {
        return;
      }

      if (!context) {
        if (isMenuOpenRef.current) {
          closeMenuAtCurrentPosition();
          return;
        }

        hideMenu();
        return;
      }

      if (
        isMenuOpenRef.current &&
        activeCellKeyRef.current &&
        context.cellKey !== activeCellKeyRef.current
      ) {
        closeMenuAtCurrentPosition();
        return;
      }

      applyMenuContext(context);
    });
  });

  useEffect(() => {
    const onPointerUp = () => {
      window.setTimeout(updateMenu, 0);
    };

    updateMenu();

    return mergeRegister(
      editor.registerUpdateListener(() => {
        updateMenu();
      }),
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          updateMenu();
          return false;
        },
        COMMAND_PRIORITY_CRITICAL
      ),
      editor.registerRootListener((rootElement, previousRootElement) => {
        previousRootElement?.removeEventListener("pointerup", onPointerUp);
        rootElement?.addEventListener("pointerup", onPointerUp);
      })
    );
  }, [editor]);

  useEffect(() => {
    const handleViewportChange = () => {
      updateMenu();
    };

    window.addEventListener("resize", handleViewportChange);
    window.addEventListener("scroll", handleViewportChange, true);

    return () => {
      window.removeEventListener("resize", handleViewportChange);
      window.removeEventListener("scroll", handleViewportChange, true);
    };
  }, []);

  const onMenuClickOutside = useEffectEvent((event: MouseEvent) => {
    const target = event.target;
    if (!(target && isDOMNode(target))) {
      return;
    }

    const menuRoot = anchorElem.querySelector(
      "[data-table-actions-root='true']"
    );
    if (menuRoot?.contains(target)) {
      return;
    }

    closeMenuAtCurrentPosition();
  });

  useEffect(() => {
    if (!isMenuOpen) {
      return;
    }

    const handleClickOutside = (event: MouseEvent) => {
      onMenuClickOutside(event);
    };

    window.addEventListener("click", handleClickOutside);
    return () => {
      window.removeEventListener("click", handleClickOutside);
    };
  }, [isMenuOpen]);

  return createPortal(
    <div
      className={
        isVisible
          ? "absolute z-40"
          : "pointer-events-none invisible absolute z-40"
      }
      data-table-actions-root="true"
      style={{ left: position.left, top: position.top }}
    >
      <Popover
        onOpenChange={(open) => {
          setMenuOpen(open);

          if (open) {
            isMenuClosingRef.current = false;
            return;
          }

          isMenuClosingRef.current = true;
        }}
        onOpenChangeComplete={(open) => {
          if (open) {
            return;
          }

          isMenuClosingRef.current = false;
          syncMenuToSelection();
        }}
        open={isMenuOpen}
      >
        <PopoverTrigger
          render={
            <Button
              aria-label="Open table actions"
              className="size-5"
              onMouseDown={(event) => {
                event.preventDefault();
                event.stopPropagation();
              }}
              onPointerDown={(event) => {
                event.stopPropagation();
              }}
              size="icon-xs"
              variant="outline"
            />
          }
        >
          <ChevronDownIcon className="size-2.5" />
        </PopoverTrigger>
        <PopoverContent
          align="start"
          className="w-56 p-0"
          side="right"
          sideOffset={8}
        >
          <TableActionMenu
            onClose={closeMenuAtCurrentPosition}
            selectionCounts={selectionCounts}
          />
        </PopoverContent>
      </Popover>
    </div>,
    anchorElem
  );
}

export function TableBehaviorPlugin() {
  const [editor] = useLexicalComposerContext();
  const isEditable = useLexicalEditable();
  const [anchorElem, setAnchorElem] = useState<HTMLElement | null>(null);

  useEffect(() => {
    return editor.registerRootListener((rootElement) => {
      setAnchorElem(rootElement?.parentElement ?? null);
    });
  }, [editor]);

  return (
    <>
      <TablePlugin hasCellBackgroundColor={false} hasHorizontalScroll />
      {isEditable && anchorElem ? (
        <TableCellActionMenuContainer anchorElem={anchorElem} />
      ) : null}
    </>
  );
}

import {
  $getTableCellNodeFromLexicalNode,
  $isTableSelection,
  type TableSelection,
} from "@lexical/table";
import { $getSelection, $isRangeSelection, type LexicalEditor } from "lexical";
import type { SelectionCounts, TableMenuContext } from "./types";

export const DEFAULT_SELECTION_COUNTS: SelectionCounts = {
  columns: 1,
  rows: 1,
};

export const areSelectionCountsEqual = (
  left: SelectionCounts,
  right: SelectionCounts
) => {
  return left.columns === right.columns && left.rows === right.rows;
};

export const resolveSelectionCounts = (
  selection: ReturnType<typeof $getSelection>
): SelectionCounts => {
  if (!$isTableSelection(selection)) {
    return DEFAULT_SELECTION_COUNTS;
  }

  const shape = (selection as TableSelection).getShape();
  return {
    columns: shape.toX - shape.fromX + 1,
    rows: shape.toY - shape.fromY + 1,
  };
};

export const readTableMenuContext = (
  editor: LexicalEditor,
  anchorElem: HTMLElement
): TableMenuContext | null => {
  const selection = $getSelection();
  if (!($isRangeSelection(selection) || $isTableSelection(selection))) {
    return null;
  }

  const tableCellNode = $getTableCellNodeFromLexicalNode(
    selection.anchor.getNode()
  );
  if (!tableCellNode?.isAttached()) {
    return null;
  }

  const tableCellElement = editor.getElementByKey(tableCellNode.getKey());
  if (!tableCellElement) {
    return null;
  }

  const cellRect = tableCellElement.getBoundingClientRect();
  const anchorRect = anchorElem.getBoundingClientRect();
  const buttonSize = 20;

  return {
    cellKey: tableCellNode.getKey(),
    position: {
      left: cellRect.right - anchorRect.left - buttonSize - 6,
      top:
        cellRect.top -
        anchorRect.top +
        Math.round((cellRect.height - buttonSize) / 2),
    },
    selectionCounts: resolveSelectionCounts(selection),
  };
};

import type { NodeKey } from "lexical";

export interface SelectionCounts {
  columns: number;
  rows: number;
}

export interface ButtonPosition {
  left: number;
  top: number;
}

export interface TableMenuContext {
  cellKey: NodeKey;
  position: ButtonPosition;
  selectionCounts: SelectionCounts;
}
